150 | func DeleteIssue(ctx context.Context, doer *user_model.User, issue *issues_model.Issue) error {
151 | 	// load issue before deleting it
152 | 	if err := issue.LoadAttributes(ctx); err != nil {
153 | 		return err
154 | 	}
155 | 	if err := issue.LoadPullRequest(ctx); err != nil {
156 | 		return err
157 | 	}
158 | 
159 | 	// delete entries in database
160 | 	attachmentPaths, err := deleteIssue(ctx, issue)
161 | 	if err != nil {
162 | 		return err
163 | 	}
164 | 	for _, attachmentPath := range attachmentPaths {
165 | 		system_model.RemoveStorageWithNotice(ctx, storage.Attachments, "Delete issue attachment", attachmentPath)
166 | 	}
167 | 
168 | 	// delete pull request related git data
169 | 	if issue.IsPull {
170 | 		if err := issue.PullRequest.LoadBaseRepo(ctx); err != nil {
171 | 			return err
172 | 		}
173 | 		if err := git.RemoveRef(ctx, issue.PullRequest.BaseRepo, issue.PullRequest.GetGitHeadRefName()); err != nil {
174 | 			return err
175 | 		}
176 | 	}
177 | 
178 | 	notify_service.DeleteIssue(ctx, doer, issue)
179 | 
180 | 	return nil
