199 | func deleteIssue(ctx context.Context, issue *issues_model.Issue) ([]string, error) {
200 | 	return db.WithTx2(ctx, func(ctx context.Context) ([]string, error) {
201 | 		if _, err := db.GetEngine(ctx).ID(issue.ID).NoAutoCondition().Delete(issue); err != nil {
202 | 			return nil, err
203 | 		}
204 | 
205 | 		if err := issues_model.DecrRepoIssueNumbers(ctx, issue.RepoID, issue.IsPull, true, issue.IsClosed); err != nil {
206 | 			return nil, err
207 | 		}
208 | 
209 | 		if err := issues_model.UpdateMilestoneCounters(ctx, issue.MilestoneID); err != nil {
210 | 			return nil, fmt.Errorf("error updating counters for milestone id %d: %w",
211 | 				issue.MilestoneID, err)
212 | 		}
213 | 
214 | 		if err := activities_model.DeleteIssueActions(ctx, issue.RepoID, issue.ID, issue.Index); err != nil {
215 | 			return nil, err
216 | 		}
217 | 
218 | 		// find attachments related to this issue and remove them
219 | 		if err := issue.LoadAttachments(ctx); err != nil {
220 | 			return nil, err
221 | 		}
222 | 
223 | 		var attachmentPaths []string
224 | 		for i := range issue.Attachments {
225 | 			attachmentPaths = append(attachmentPaths, issue.Attachments[i].RelativePath())
226 | 		}
227 | 
228 | 		// delete all database data still assigned to this issue
229 | 		if err := db.DeleteBeans(ctx,
230 | 			&issues_model.ContentHistory{IssueID: issue.ID},
231 | 			&issues_model.Comment{IssueID: issue.ID},
232 | 			&issues_model.IssueLabel{IssueID: issue.ID},
