284 | // DeleteIssuesByRepoID deletes issues by repositories id
285 | func DeleteIssuesByRepoID(ctx context.Context, repoID int64) (attachmentPaths []string, err error) {
286 | 	for {
287 | 		issues := make([]*issues_model.Issue, 0, db.DefaultMaxInSize)
288 | 		if err := db.GetEngine(ctx).
289 | 			Where("repo_id = ?", repoID).
290 | 			OrderBy("id").
291 | 			Limit(db.DefaultMaxInSize).
292 | 			Find(&issues); err != nil {
293 | 			return nil, err
294 | 		}
295 | 
296 | 		if len(issues) == 0 {
297 | 			break
298 | 		}
299 | 
300 | 		for _, issue := range issues {
301 | 			issueAttachPaths, err := deleteIssue(ctx, issue)
302 | 			if err != nil {
303 | 				return nil, fmt.Errorf("deleteIssue [issue_id: %d]: %w", issue.ID, err)
304 | 			}
305 | 
306 | 			attachmentPaths = append(attachmentPaths, issueAttachPaths...)
307 | 		}
308 | 	}
309 | 
310 | 	return attachmentPaths, err
